"""Visual research story with CSV-derived comparisons and visible limitations."""
from html import escape
from .story_data import (ABLATIONS, DOMAINS, EXCLUDED, FINAL_ROWS, HEADLINE, LABELS,
                         REPORT_URL, SELECTOR_ROWS, SOURCE_COMMIT, SOURCE_ROOT,
                         paired, source_url, summarize)

