NOVELTY = r'''
<section id="perspectives" class="research-section"><div class="wrap">
 <p class="overline">The method / Make the evidence inspectable</p>
 <div class="research-heading reveal"><h2>Separate the questions.<br><span>Connect the evidence.</span></h2><p>Both methods generate or check constraints. AgentReroute organizes checks by perspective, then gives a model the evidence and freedom to select across the full trace.</p></div>
 <div class="perspective-comparison reveal">
  <article class="approach baseline-approach"><div class="approach-label"><span class="engine-mark">Rx</span><div><h3>AgentRx</h3><span>The joint control</span></div></div><div class="trace-strip">Recorded trajectory → constraints → checks</div><div class="diagram-join" aria-hidden="true">↓</div><div class="joint-judge"><span class="tiny-label">JOINT ATTRIBUTION</span><strong>“Where did this go wrong?”</strong><p>Assess the trace and violation evidence together.</p></div><div class="diagram-join" aria-hidden="true">↓</div><div class="decision-card">Critical step + agent + explanation</div><p class="approach-note">The baseline retains its constraint generation, checking, and final joint judgment. Its exact-step score is measured on this published subset.</p></article>
  <article class="approach multi-approach"><div class="approach-label"><span class="engine-mark">↗</span><div><h3>AgentReroute</h3><span>Perspective evidence + LLM selection</span></div></div><div class="trace-strip">The same recorded trace, checked prefix by prefix</div><div class="lens-fan" aria-hidden="true"><i></i><i></i><i></i></div><div class="lens-cards"><div class="lens-card intent"><span>01 / INTENT &amp; PLAN</span><strong>Does the action serve the goal?</strong><small>Intent and plan alignment.</small></div><div class="lens-card tools"><span>02 / EXECUTION</span><strong>Did the operation behave correctly?</strong><small>Tool use and execution.</small></div><div class="lens-card context"><span>03 / GROUNDING</span><strong>Are the facts supported?</strong><small>Context and handoffs.</small></div></div><div class="diagram-join" aria-hidden="true">↓</div><div class="decision-card"><strong>Candidate evidence → full-trace LLM selector</strong><span>A step outside the candidate pool remains selectable.</span></div><div class="feedback-loop"><span aria-hidden="true">◎</span><p>Untrained THETA0 is frozen.<br><strong>Inference performs attribution without a policy update.</strong></p></div></article>
 </div><p class="research-note">Checks inspect only the observed prefix at each step. The selector receives the full recorded trace and candidate evidence; reference fault labels are reserved for scoring after prediction. Agent blame alone cannot localize a step in a single-agent trace.</p>
</div></section>
'''


def chart(domain, arms, *, ablation=False):
    rows = []
    for arm in arms:
        lo, hi = arm['ci']
        note = f"{arm['hits']}/{arm['n']} exact steps · 95% CI [{lo:.1f}, {hi:.1f}]"
        if not ablation and arm['variant'] != 'agentrx':
            pair = paired(FINAL_ROWS, 'agentrx', arm['variant'], domain)
            note += f" · Δ {pair['delta']:+.1f} pp · p={pair['p']:.4f}"
        rows.append(f'''<div class="benchmark-row {'agentrx' if arm['variant']=='agentrx' else 'agentreroute'}"><div class="bar-label"><span>{escape(arm['label'])}<small>{escape(note)}</small></span><strong>{arm['accuracy']:.1f}%</strong></div><div class="bar-track" aria-hidden="true"><span style="--bar:{arm['accuracy']:.6f}%"></span></div></div>''')
    missing = '<p class="benchmark-context">Written checks: <strong>not reportable</strong> for magentic. See excluded runs below.</p>' if domain == 'magentic' and not ablation else ''
    return f'''<figure class="benchmark-chart"><figcaption><span class="tiny-label">EXACT FAULT-STEP ACCURACY · n={arms[0]['n']}</span><h3>{escape(DOMAINS[domain])}</h3></figcaption><div class="axis-note"><span>0 — 100%</span><span>Higher is better</span></div>{''.join(rows)}{missing}</figure>'''


def status_table(rows, variants, caption):
    body = []
    for domain in DOMAINS:
        for variant in variants:
            arm = summarize(rows, domain, variant)
            statuses = ', '.join(f'{name}: {count}' for name, count in sorted(arm['statuses'].items()))
            body.append(f"<tr><th scope='row'>{domain} / {escape(LABELS[variant])}</th><td>{arm['n']}</td><td>{arm['fallbacks']}</td><td>{arm['selector_errors']}</td><td>{escape(statuses)}</td></tr>")
    return f'''<div class="benchmark-table-scroll"><table><caption>{escape(caption)}</caption><thead><tr><th scope="col">Arm</th><th scope="col">Cases</th><th scope="col">Fallback flags</th><th scope="col">Selector errors</th><th scope="col">Recorded job status</th></tr></thead><tbody>{''.join(body)}</tbody></table></div>'''


def benchmarks():
    total = sum(arms[0]['n'] for arms in HEADLINE.values())
    ablation = paired(SELECTOR_ROWS, 'mp_rl_top1', 'mp_rl_select_trace')
    panels = ''.join(f'''<div id="benchmark-{name}" class="benchmark-panels reveal" {'hidden' if name!='quality' else ''}><div class="benchmark-dataset">{''.join(chart(domain, arms, ablation=name=='ablation') for domain, arms in groups.items())}</div></div>''' for name, groups in [('quality', HEADLINE), ('ablation', ABLATIONS)])
    excluded = ''.join(f"<li><code>{arm['variant']}</code> / {arm['domain']}: {arm['selector_errors']}/{arm['n']} selector errors; excluded as provider-contaminated.</li>" for arm in EXCLUDED)
    tainted_magentic = next(arm for arm in EXCLUDED if arm['domain']=='magentic' and arm['variant']=='synth_select_p5')
    return f'''
<section id="benchmark-results" class="benchmark-section"><div class="wrap">
 <div class="benchmark-topline"><p class="overline">The evidence / Published AgentRx subset</p><span class="evidence-badge">{total} recorded traces · exact step match</span></div>
 <div class="research-heading reveal"><h2>Small improvements.<br><span>Wide uncertainty.</span></h2><p>The reportable arms improve exact fault-step accuracy numerically. None of their paired differences against AgentRx reaches statistical significance.</p></div>
 <p id="benchmark-provenance">Gemini 3.1 Flash Lite · temperature 0 · frozen THETA0.<br>Saved research evidence; the interactive comparison below is a separate run.</p>
 <div class="benchmark-toolbar"><div class="benchmark-switch" role="group" aria-label="Benchmark view"><button type="button" data-benchmark="quality" aria-pressed="true">Headline comparison</button><button type="button" data-benchmark="ablation" aria-pressed="false">Selector ablation</button></div></div>
 {panels}
 <div class="benchmark-context"><p><strong>What the ablation isolates</strong>All selector-ablation arms have zero logged selector transport errors. Full-trace selection beats frozen top-1 on {ablation['wins']} paired cases and loses on {ablation['losses']} across {ablation['n']} traces: exact two-sided McNemar p={ablation['p']:.4f}. This is an ablation result against the linear policy; it does not establish a significant gain over AgentRx. Fallback flags remain visible below.</p></div>
 <details class="benchmark-methodology"><summary>Uncertainty, failures, exclusions &amp; pinned sources</summary>
 <p>Every percentage uses all recorded cases in that domain. Bars show exact fault-step match, with 95% Wilson intervals; paired p-values use the exact two-sided McNemar test on matching case IDs. Errors and abstentions stay in the denominator. The published subset is distinct from our generated development corpus.</p>
 {status_table(FINAL_ROWS, ['agentrx', 'seeds_select', 'synth_select_p10'], 'Headline and written-check run diagnostics, including excluded magentic synthesis')}
 <p><strong>Fallback flags differ from selector transport errors.</strong>Fixed and written tau runs each log {HEADLINE['tau'][1]['fallbacks']}/{HEADLINE['tau'][1]['n']} fallback flags with zero selector errors. The CSV does not record each fallback reason. Partial checker statuses also appear in the control and written-check arm; reportable does not mean every internal call succeeded.</p>
 <p><strong>Excluded arms:</strong> the analysis flags any arm with selector errors on at least 20% of its cases. Their fallback predictions mix in the frozen linear ranking.</p><ul>{excluded}</ul>
 <p><strong>Source discrepancy:</strong> the README describes the magentic p5 failure as 19/19 at an earlier point. The committed final CSV contains {tainted_magentic['selector_errors']}/{tainted_magentic['n']}; the diagnostics here follow that CSV. Its excluded accuracy is not plotted.</p>
 <p><strong>Open result:</strong> a later clean magentic synthesis attempt failed at the provider billing cap (HTTP 402) and was voided, according to the results README. No clean written-check figure is available. These CSVs do not expose every synthesis-call status, so they cannot certify that all constraint-writing calls succeeded.</p>
 {status_table(SELECTOR_ROWS, ['mp_rl_top1', 'mp_rl_select_pool', 'mp_rl_select_trace'], 'Selector ablation diagnostics')}
 <p><a href="{source_url()}" target="_blank" rel="noopener">Final per-case CSV ↗</a> · <a href="{source_url('selector')}" target="_blank" rel="noopener">Selector per-case CSV ↗</a> · <a href="{REPORT_URL}" target="_blank" rel="noopener">Results and caveats ↗</a> · <a href="{SOURCE_ROOT}analyze_run.py" target="_blank" rel="noopener">Reproduce the analysis ↗</a><br>Sources pinned to <code>{SOURCE_COMMIT}</code>. Local evidence bytes are checked against that revision.</p>
 </details>
 <p class="benchmark-footnote">These are attribution results. A correct diagnosis does not itself establish successful recovery, faster completion, or lower cost.</p>
 <a class="text-link research-cta" href="#compare-engines">Inspect a new comparison <span>↓</span></a>
</div></section>'''


def impact():
    arms = [summarize(FINAL_ROWS, domain, 'seeds_select') for domain in DOMAINS]
    stats = ''.join(f'''<article class="impact-stat"><span class="tiny-label">{escape(DOMAINS[arm['domain']]).upper()} / FIXED CHECKS</span><strong>{arm['recall']:.1f}<span>%</span></strong><h3>Candidate-pool recall</h3><p>The true fault appears in {arm['in_pool_n']}/{arm['n']} pools. The full-trace selector gets {arm['in_pool_hits']}/{arm['in_pool_n']} in-pool cases correct and {arm['out_pool_hits']}/{arm['n']-arm['in_pool_n']} out-of-pool cases correct.</p></article>''' for arm in arms)
    written = summarize(FINAL_ROWS, 'tau', 'synth_select_p10')
    return f'''
<section id="impact" class="impact-section"><div class="wrap">
 <p class="overline">What we learned / The evidence bottleneck</p>
 <h2 class="reveal">Find better candidates.<br><span>Then ask which one matters.</span></h2>
 <p class="impact-intro">A selector works better when the evidence includes the real fault. Candidate-pool recall asks a simple question: how often does the true step appear anywhere among the candidates?</p>
 <div class="impact-targets"><div class="target-caption"><span class="evidence-badge">Derived from the published subset</span><h3>Selection needs<br>useful evidence.</h3><p>Pool recall limits a selector confined to the pool. The full-trace selector can choose outside it, but does so less successfully in these observations.</p></div>{stats}</div>
 <p class="impact-caveat">Written checks raise tau recall to {written['recall']:.1f}% ({written['in_pool_n']}/{written['n']}). This decomposition describes the recorded outcomes; it is not a causal estimate or a forecast of future accuracy.</p>
 <div class="method-heading"><h3>Three limits.<br>A clearer next question.</h3><p>Research progress includes negative results.</p></div>
 <div class="method-cards"><article><span class="tiny-label">THE DOMAIN GAP</span><h4>Roles change the evidence.</h4><p>Published tau traces are effectively single-agent, while the development corpus uses specialized agents. Routing and handoff checks have fewer opportunities to contribute on the published tasks.</p></article><article><span class="tiny-label">THE NEGATIVE RESULTS</span><h4>Keep the policy frozen.</h4><p>Training hurt held-out attribution in the development experiment. The repair-and-verify cascade did not improve published tau attribution. Lower violations after a rewrite did not reliably identify the original fault.</p></article><article class="method-highlight"><span class="tiny-label">THE OPEN DIRECTION</span><h4>Improve constraint writing.</h4><p>Study whether better checks bring the true fault into the candidate pool. Evaluate pool recall directly, then test any resulting accuracy gain on separate evidence.</p></article></div>
 <div class="impact-closing"><p>Inspect the reasoning. Keep the uncertainty visible.<br><strong>The next claim needs another measurement.</strong></p><a class="pill-link" href="{REPORT_URL}" target="_blank" rel="noopener">Read the research notes <span>↗</span></a></div>
</div></section>'''

